const raw = $input.first().json;
const body = raw.body || raw;
if (body.senderId) {
  const text = String(body.text || '').trim();
  const fileId = String(body.fileId || '').trim();
  const hadVoice = !text && !!fileId;
  return [{ json: {
    adminId: '0',
    senderId: String(body.senderId),
    chatId: String(body.senderId),
    firstName: body.firstName || 'cliente',
    text: text || (hadVoice ? '' : '[mensagem sem texto]'),
    hadVoice,
    fileId,
    voiceError: ''
  } }];
}
return [{ json: {
  adminId: '0',
  senderId: '',
  chatId: '',
  firstName: 'cliente',
  text: '[mensagem sem texto]',
  hadVoice: false,
  fileId: '',
  voiceError: ''
} }];

const prep = $('Preparar (texto/voz)').first().json;
const prev = $input.first().json;
let out = String(prev.output || prev.text || '').trim();
const escalate = /ESCALATE\s*:\s*YES/i.test(out);
out = out.replace(/\s*ESCALATE\s*:\s*(YES|NO)\s*/gi, '').trim();
return [{ json: {
  chatId: String(prep.chatId || ''),
  senderId: String(prep.senderId || ''),
  outMessage: out || 'Sem resposta.',
  escalate
} }];

const prep = $('Preparar (texto/voz)').first().json;
const j = $input.first().json || {};
let text = String(j.text || '').trim();
let voiceError = '';
if (!text) {
  voiceError = String(j.error?.message || j.message || 'whisper vazio').slice(0, 180);
  text = '[áudio recebido, mas não consegui transcrever]';
}
return [{ json: { ...prep, text, hadVoice: true, voiceError } }];

